(()=>{
'use strict';
const $=id=>document.getElementById(id);
const $$=sel=>[...document.querySelectorAll(sel)];
const DB_NAME='gs_asistente_db_v2', DB_VERSION=1;
let db, currentVisit=null, editorPhotoRef=null, originalEditorImage=null;

const sedeMunicipios={
  'FACATATIVÁ':['EL PEÑÓN','EL ROSAL','FACATATIVÁ','FUNZA','GUAYABAL DE SÍQUIME','LA VEGA','MADRID','MOSQUERA','NIMAIMA','NOCAIMA','PUERTO SALGAR','QUEBRADANEGRA','TOPAIPÍ','ÚTICA','VERGARA','VIANÍ','VILLETA','YACOPÍ','ZIPACÓN'],
  'FUSAGASUGÁ':['ARBELÁEZ','BOGOTÁ','CABRERA','CABUYARO','CÁQUEZA','CHIPAQUE','CHOACHÍ','EL CALVARIO','FÓMEQUE','FOSCA','FUSAGASUGÁ','GRANADA','GUAYABETAL','GUTIÉRREZ','ICONONZO','MEDINA','PANDI','PARATEBUENO','PASCA','QUETAME','SAN BERNARDO','SAN JUANITO','SIBATÉ','SILVANIA','SOACHA','TIBACUY','UBAQUE','UNE','VENECIA'],
  'GIRARDOT':['AGUA DE DIOS','ANAPOIMA','ANOLAIMA','APULO','BELTRÁN','CACHIPAY','COELLO','FLANDES','GIRARDOT','GUATAQUÍ','JERUSALÉN','LA MESA','EL COLEGIO','NARIÑO','NILO','PULÍ','QUIPILE','RICAURTE','SAN ANTONIO DEL TEQUENDAMA','TENA','TOCAIMA','VIOTÁ'],
  'ZIPAQUIRÁ':['BUENAVISTA','CAJICÁ','CALDAS','CARMEN DE CARUPA','CHOCONTÁ','COGUA','FÚQUENE','GACHALÁ','GACHETÁ','GUACHETÁ','GUASCA','JUNÍN','LA CALERA','MANTA','NEMOCÓN','PACHO','SESQUILÉ','SIMIJACA','SOPÓ','SUSA','SUTATAUSA','TABIO','TAUSA','TENJO','TIBIRITA','TOCANCIPÁ','UBATÉ','VILLAGÓMEZ','VILLAPINZÓN','ZIPAQUIRÁ']
};
const areaTypes=['Vereda','Barrio','Localidad','Centro poblado','Caserío','Resguardo','Corregimiento','Otro'];
const techGroups={
  mt:{title:'Tipo de red MT',items:['MT abierta','MT trenzada','MT compacta','MT subterránea','No visible','No aplica']},
  bt:{title:'Tipo de red BT',items:['BT abierta','BT trenzada','BT preensamblada','BT subterránea','Mixta','No visible','No aplica']},
  equipment:{title:'Equipos identificados',items:['Seccionador','Reconectador','Cortacircuito fusible','Pararrayos','DPS','Regulador de tensión','Banco de condensadores','No se identifican']},
  networkState:{title:'Estado de redes',items:['Buen estado general','Condición operativa adecuada','Requiere mantenimiento preventivo','Requiere mantenimiento correctivo','Conductores deteriorados','Empalmes visibles','Empalmes artesanales','Flecha excesiva','Baja altura','Vegetación cercana','Cruce por predios privados','Cruce de vía pública','Riesgo de contacto','Red improvisada','Red normalizada','Red parcialmente normalizada']},
  poleType:{title:'Tipo de postería',items:['Hormigón','Madera','Metálica','Fibra de vidrio','Mixta','No visible']},
  poleState:{title:'Estado de postes',items:['Buen estado','Inclinados','Fisuras','Corrosión','Pudrición','Base socavada','Cimentación expuesta','Riostras deficientes','Altura insuficiente','Requiere reemplazo','Sobrecarga de herrajes']},
  transformerState:{title:'Estado del transformador',items:['Buen estado visual','Identificación legible','Placa ilegible','Fugas de aceite','Corrosión','Ruido anormal','Sobrecarga aparente','Puesta a tierra visible','Sin puesta a tierra visible','Requiere inspección especializada']},
  construction:{title:'Condición constructiva',items:['Infraestructura ENEL','Infraestructura comunitaria','Infraestructura particular','Construcción normalizada','Construcción parcialmente normalizada','Construcción artesanal']},
  coverage:{title:'Cobertura y necesidad técnica',items:['Cobertura adecuada','Requiere extensión BT','Requiere nuevo transformador','Requiere aumento de capacidad','Requiere reubicación','Requiere normalización','Requiere replanteo','Requiere poda','Requiere mantenimiento','No aplica']}
};
const territoryGroups={
  community:{title:'Características de la comunidad',items:['Comunidad campesina','Comunidad indígena','Comunidad afrodescendiente','Población migrante','Víctimas del conflicto','Comunidad organizada','JAC activa','Crecimiento reciente','Alta densificación','Vivienda dispersa']},
  priority:{title:'Población prioritaria',items:['Usuarios tecnodependientes','Personas con discapacidad','Personas mayores','Niños, niñas y adolescentes','Mujeres cabeza de hogar','Población con tratamiento médico permanente']},
  property:{title:'Condición predial',items:['Propiedad privada','Posesión','Invasión / ocupación informal','Bien fiscal','Zona de protección','Reserva ambiental','Sin información']},
  risks:{title:'Riesgos no eléctricos',items:['Remoción en masa','Inundación','Riesgo geológico','Erosión','Caída de rocas','Riesgo biológico','Riesgo locativo','Orden público']},
  access:{title:'Tipo de acceso',items:['Vía pavimentada','Placa huella','Vía en afirmado','Vía destapada','Camino veredal','Sendero peatonal','Acceso solo en moto','Acceso solo a pie','Sin acceso vehicular directo']},
  road:{title:'Estado de las vías',items:['Buen estado','Transitable con precaución','Presencia de barro','Superficie deslizante','Mucha piedra','Huecos','Pérdida de banca','Pendiente pronunciada','Curvas cerradas','Paso angosto','Cruce de quebrada','Dificultad en temporada de lluvias','Ingreso difícil para vehículos pesados']}
};
const managementTopics=['Alcance de la visita','Norma técnica','Redes internas','Redes externas','Tipos de predios susceptibles de normalización','Proceso previo de Redes','Etapas del proceso de normalización','Gestión documental futura','Responsabilidades de la comunidad','Atención de inquietudes'];
const glossary={
 'UNC':'Usuario No Cliente: predio que requiere o recibe el servicio de energía, pero no cuenta con una cuenta comercial activa asociada.',
 'BT':'Baja Tensión: red destinada a la distribución final de energía hacia los usuarios.',
 'MT':'Media Tensión: red que alimenta los transformadores de distribución.',
 'CD':'Centro de Distribución: transformador y la infraestructura inmediata que soporta el tendido de red BT asociado.',
 'Servicio directo':'Conexión al servicio de energía sin medición comercial normalizada.',
 'Placa huella':'Estructura de concreto utilizada para mejorar la transitabilidad en vías rurales.',
 'Red artesanal':'Infraestructura construida mediante soluciones improvisadas o sin evidencia de cumplimiento de criterios técnicos aplicables.',
 'Tecnodependiente':'Persona que requiere equipos eléctricos de soporte para mantener funciones vitales o su tratamiento médico.',
 'Favorable':'Clasificación aplicable únicamente a infraestructura ENEL que presenta condiciones técnicas adecuadas y sin requerimientos relevantes.',
 'Medio':'Clasificación para infraestructura que requiere seguimiento o intervenciones puntuales; es el máximo estado para CD comunitarios o particulares.',
 'Crítico':'Clasificación para infraestructura con riesgos, deterioro o limitaciones que requieren intervención prioritaria.'
};

function uuid(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}
function nowISO(){return new Date().toISOString()}
function dateLocal(d=new Date()){const z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}`}
function timeLocal(d=new Date()){return `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
function escapeHtml(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function showScreen(id){$$('.screen').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');scrollTo({top:0,behavior:'smooth'})}
function openModal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').classList.add('show')}
function closeModal(){$('modal').classList.remove('show');$('modalBody').innerHTML=''}
function activeArea(){return currentVisit?.areas?.find(a=>a.id===currentVisit.activeAreaId)||currentVisit?.areas?.[0]||null}
function areaLabel(a){return a?`${a.type||'Área'} ${a.name||'Sin nombre'}${a.sector?` / ${a.sector}`:''}`:'Sin área activa'}

function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=e=>{const d=e.target.result;if(!d.objectStoreNames.contains('visits'))d.createObjectStore('visits',{keyPath:'id'});if(!d.objectStoreNames.contains('meta'))d.createObjectStore('meta',{keyPath:'key'})};r.onsuccess=()=>{db=r.result;resolve(db)};r.onerror=()=>reject(r.error)})}
function tx(store,mode='readonly'){return db.transaction(store,mode).objectStore(store)}
function idbGet(store,key){return new Promise((res,rej)=>{const r=tx(store).get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function idbPut(store,value){return new Promise((res,rej)=>{const r=tx(store,'readwrite').put(value);r.onsuccess=()=>res(value);r.onerror=()=>rej(r.error)})}
function idbDelete(store,key){return new Promise((res,rej)=>{const r=tx(store,'readwrite').delete(key);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
function idbAll(store){return new Promise((res,rej)=>{const r=tx(store).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
async function nextVisitId(){const today=dateLocal().replaceAll('-','');const key=`counter_${today}`;const rec=await idbGet('meta',key)||{key,value:0};rec.value++;await idbPut('meta',rec);return `${today}${String(rec.value).padStart(4,'0')}`}
function blankVisit(id){return {id,createdAt:nowISO(),updatedAt:nowISO(),date:dateLocal(),start:timeLocal(),sede:'',municipio:'',zona:'',status:'En progreso',activeAreaId:null,areas:[],cds:[],territory:{},territoryObs:'',management:{topics:[],obs:'',nextAction:'',meeting:'No'},findings:[],people:[],pendings:[],reportGenerated:false,reportDate:'',nitsSummary:''}}
let saveTimer;
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(saveCurrent,300)}
async function saveCurrent(){if(!currentVisit)return;collectTopFields();currentVisit.updatedAt=nowISO();await idbPut('visits',currentVisit);renderVisitHeader();renderVisitList()}
function collectTopFields(){if(!currentVisit)return;currentVisit.date=$('visitDate').value;currentVisit.start=$('visitStart').value;currentVisit.sede=$('sede').value;currentVisit.municipio=$('municipio').value;currentVisit.zona=$('zona').value;currentVisit.territoryObs=$('territoryObs').value;currentVisit.management.obs=$('managementObs').value;currentVisit.management.nextAction=$('nextAction').value;currentVisit.management.meeting=$('communityMeeting').value}

function fillSede(){const s=$('sede');s.innerHTML='<option value="">Selecciona…</option>'+Object.keys(sedeMunicipios).map(x=>`<option>${x}</option>`).join('')}
function fillMunicipio(value=''){const list=sedeMunicipios[$('sede').value]||[];$('municipio').innerHTML='<option value="">Selecciona sede…</option>'+list.map(x=>`<option>${x}</option>`).join('');$('municipio').value=value}
function bindAutosave(){['visitDate','visitStart','sede','municipio','zona','territoryObs','managementObs','nextAction','communityMeeting'].forEach(id=>$(id).addEventListener('input',scheduleSave));$('sede').addEventListener('change',()=>{fillMunicipio();scheduleSave()})}

async function createVisit(){const id=await nextVisitId();currentVisit=blankVisit(id);await idbPut('visits',currentVisit);loadVisitToUI();showScreen('visitScreen');toast('Nueva visita creada')}
async function openVisit(id){currentVisit=await idbGet('visits',id);if(!currentVisit)return;normalizeVisit();loadVisitToUI();showScreen('visitScreen')}
function normalizeVisit(){currentVisit.areas||=[];currentVisit.cds||=[];currentVisit.territory||={};currentVisit.management||={topics:[],obs:'',nextAction:'',meeting:'No'};currentVisit.findings||=[];currentVisit.people||=[];currentVisit.pendings||=[]}
function loadVisitToUI(){normalizeVisit();$('visitId').value=currentVisit.id;$('visitDate').value=currentVisit.date||dateLocal();$('visitStart').value=currentVisit.start||timeLocal();$('sede').value=currentVisit.sede||'';fillMunicipio(currentVisit.municipio||'');$('zona').value=currentVisit.zona||'';$('territoryObs').value=currentVisit.territoryObs||'';$('managementObs').value=currentVisit.management.obs||'';$('nextAction').value=currentVisit.management.nextAction||'';$('communityMeeting').value=currentVisit.management.meeting||'No';renderCheckGroups();renderAreas();renderCDs();renderFindings();renderPhotoGallery();renderPeople();renderPendings();renderVisitHeader()}
function renderVisitHeader(){if(!currentVisit)return;const label=[currentVisit.municipio,activeArea()?.name].filter(Boolean).join(' · ')||'Visita sin ubicación';$('visitHeading').textContent=label;$('visitIdLabel').textContent=`ID ${currentVisit.id}`;$('visitStatus').textContent=currentVisit.reportGenerated?'Informe generado':'En progreso';$('visitStatus').className=`status ${currentVisit.reportGenerated?'generated':'in-progress'}`}
async function renderVisitList(){const visits=(await idbAll('visits')).sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''));$('activeVisitsCount').textContent=visits.filter(v=>!v.reportGenerated).length;$('reportsCount').textContent=visits.filter(v=>v.reportGenerated).length;$('pendingCount').textContent=visits.reduce((n,v)=>n+(v.pendings||[]).filter(p=>!['Cumplido','Cerrado'].includes(p.status)).length,0);const box=$('visitList');if(!visits.length){box.innerHTML='<div class="empty">Aún no hay visitas guardadas.</div>';return}box.innerHTML=visits.map(v=>{const a=v.areas?.find(x=>x.id===v.activeAreaId)||v.areas?.[0];return `<div class="visit-row"><div><h4>${escapeHtml(v.municipio||'Municipio pendiente')} ${a?.name?`· ${escapeHtml(a.name)}`:''}</h4><p>ID ${v.id} · ${v.date||''} · ${v.reportGenerated?'Informe generado':'En progreso'}</p><p>${v.areas?.length||0} áreas · ${v.cds?.length||0} CD · ${v.findings?.length||0} hallazgos</p></div><div class="item-actions"><button class="primary small" data-open="${v.id}">Continuar</button><button class="secondary small" data-backup="${v.id}">Respaldo</button><button class="danger small" data-delete="${v.id}">Eliminar</button></div></div>`}).join('');box.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openVisit(b.dataset.open));box.querySelectorAll('[data-backup]').forEach(b=>b.onclick=async()=>exportBackup(await idbGet('visits',b.dataset.backup)));box.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(confirm('¿Eliminar esta visita de forma permanente?')){await idbDelete('visits',b.dataset.delete);renderVisitList()}})}

function checkboxGroup(key,title,items,selected=[],prefix='territory'){return `<div class="check-group"><h4>${title}</h4><div class="check-grid three">${items.map((x,i)=>`<label class="check-item"><input type="checkbox" data-check-prefix="${prefix}" data-check-key="${key}" value="${escapeHtml(x)}" ${selected.includes(x)?'checked':''}>${escapeHtml(x)}</label>`).join('')}</div></div>`}
function renderCheckGroups(){const t=$('territoryChecks');t.innerHTML=Object.entries(territoryGroups).map(([k,g])=>checkboxGroup(k,g.title,g.items,currentVisit.territory[k]||[],'territory')).join('');$('managementChecks').innerHTML=checkboxGroup('topics','Temas socializados',managementTopics,currentVisit.management.topics||[],'management');$$('[data-check-prefix]').forEach(c=>c.onchange=()=>{const p=c.dataset.checkPrefix,k=c.dataset.checkKey;const root=p==='territory'?currentVisit.territory:currentVisit.management;root[k]=$$(`[data-check-prefix="${p}"][data-check-key="${k}"]:checked`).map(x=>x.value);scheduleSave()})}

function renderAreas(){const box=$('areasList');if(!currentVisit.areas.length){box.innerHTML='<div class="empty">Agrega la primera vereda, barrio o localidad para comenzar el recorrido.</div>';return}box.innerHTML=currentVisit.areas.map(a=>`<div class="item-card ${a.id===currentVisit.activeAreaId?'active-item':''}"><div class="item-top"><div><h4>${escapeHtml(areaLabel(a))}</h4><p>${a.gpsStatus==='Exacto'||a.gpsStatus==='Aproximado / referencia'?`📍 ${a.lat||''}, ${a.lng||''} · ${a.gpsStatus}`:'Sin GPS'}</p></div><div class="item-actions"><button class="${a.id===currentVisit.activeAreaId?'primary':'secondary'} small" data-area-active="${a.id}">${a.id===currentVisit.activeAreaId?'Área activa':'Activar'}</button><button class="secondary small" data-area-edit="${a.id}">Editar</button><button class="danger small" data-area-delete="${a.id}">Eliminar</button></div></div></div>`).join('');box.querySelectorAll('[data-area-active]').forEach(b=>b.onclick=()=>{currentVisit.activeAreaId=b.dataset.areaActive;scheduleSave();renderAreas();renderVisitHeader()});box.querySelectorAll('[data-area-edit]').forEach(b=>b.onclick=()=>showAreaModal(currentVisit.areas.find(a=>a.id===b.dataset.areaEdit)));box.querySelectorAll('[data-area-delete]').forEach(b=>b.onclick=()=>{if(confirm('¿Eliminar esta área? Los registros asociados conservarán su referencia textual.')){currentVisit.areas=currentVisit.areas.filter(a=>a.id!==b.dataset.areaDelete);if(currentVisit.activeAreaId===b.dataset.areaDelete)currentVisit.activeAreaId=currentVisit.areas[0]?.id||null;scheduleSave();renderAreas()}})}
function showAreaModal(a=null){const item=a||{id:uuid(),type:'Vereda',name:'',sector:'',gpsStatus:'No capturado',lat:'',lng:'',precision:''};openModal(a?'Editar área':'Agregar área',`<div class="grid two"><div><label>Tipo</label><select id="mAreaType">${areaTypes.map(x=>`<option ${x===item.type?'selected':''}>${x}</option>`).join('')}</select></div><div><label>Nombre *</label><input id="mAreaName" value="${escapeHtml(item.name)}"></div><div><label>Sector (opcional)</label><input id="mAreaSector" value="${escapeHtml(item.sector)}"></div><div><label>Estado GPS</label><select id="mAreaGps"><option>No capturado</option><option>Exacto</option><option>Aproximado / referencia</option></select></div><div><label>Latitud</label><input id="mAreaLat" value="${item.lat||''}"></div><div><label>Longitud</label><input id="mAreaLng" value="${item.lng||''}"></div></div><div class="form-actions"><button id="captureAreaGps" class="secondary">📍 Capturar ubicación actual</button><button id="saveArea" class="primary">Guardar área</button></div>`);$('mAreaGps').value=item.gpsStatus;$('captureAreaGps').onclick=()=>captureGps('mAreaLat','mAreaLng','mAreaGps');$('saveArea').onclick=()=>{const name=$('mAreaName').value.trim();if(!name)return toast('Escribe el nombre del área');Object.assign(item,{type:$('mAreaType').value,name,sector:$('mAreaSector').value.trim(),gpsStatus:$('mAreaGps').value,lat:$('mAreaLat').value,lng:$('mAreaLng').value});if(!a)currentVisit.areas.push(item);currentVisit.activeAreaId=item.id;closeModal();scheduleSave();renderAreas();renderVisitHeader()}}
function captureGps(latId,lngId,statusId){if(!navigator.geolocation)return toast('GPS no disponible');toast('Capturando ubicación…');navigator.geolocation.getCurrentPosition(p=>{$(latId).value=p.coords.latitude.toFixed(7);$(lngId).value=p.coords.longitude.toFixed(7);$(statusId).value=p.coords.accuracy<=15?'Exacto':'Aproximado / referencia';toast(`GPS capturado · precisión ${Math.round(p.coords.accuracy)} m`)},()=>toast('No fue posible capturar GPS'),{enableHighAccuracy:true,timeout:15000,maximumAge:10000})}

function renderCDs(){const box=$('cdList');if(!currentVisit.cds.length){box.innerHTML='<div class="empty">No se han registrado CD o transformadores.</div>';return}box.innerHTML=currentVisit.cds.map(c=>`<div class="item-card"><div class="item-top"><div><h4>⚡ ${escapeHtml(c.code||'CD sin identificar')}</h4><p>${escapeHtml(c.kva||'N.V.')} kVA · ${escapeHtml(c.property||'Propiedad no definida')} · ${escapeHtml(c.areaLabel||'Sin área')}</p><div><span class="tag ${c.validatedState==='Favorable'?'green':c.validatedState==='Crítico'?'red':'amber'}">${escapeHtml(c.validatedState||c.suggestedState||'No evaluado')}</span>${(c.mt||[]).map(x=>`<span class="tag">${escapeHtml(x)}</span>`).join('')}</div></div><div class="item-actions"><button class="secondary small" data-cd-edit="${c.id}">Editar</button><button class="danger small" data-cd-delete="${c.id}">Eliminar</button></div></div><p class="hint">${escapeHtml(c.nitsDescription||'La descripción se construirá con las opciones técnicas y la observación del gestor.')}</p></div>`).join('');box.querySelectorAll('[data-cd-edit]').forEach(b=>b.onclick=()=>showCdModal(currentVisit.cds.find(c=>c.id===b.dataset.cdEdit)));box.querySelectorAll('[data-cd-delete]').forEach(b=>b.onclick=()=>{if(confirm('¿Eliminar este CD?')){currentVisit.cds=currentVisit.cds.filter(c=>c.id!==b.dataset.cdDelete);scheduleSave();renderCDs()}})}
function showCdModal(c=null){const a=activeArea();if(!a&&!c)return toast('Primero agrega y activa un área recorrida');const item=c||{id:uuid(),areaId:a.id,areaLabel:areaLabel(a),code:'',kva:'',property:'ENEL',gpsStatus:'No capturado',lat:'',lng:'',precision:'',mt:[],bt:[],equipment:[],networkState:[],poleType:[],poleState:[],transformerState:[],construction:[],coverage:[],obs:'',clients:0,unc:0,susp:0,baldios:0,suggestedState:'',validatedState:'',priority:'Media',nitsDescription:''};let checks=Object.entries(techGroups).map(([k,g])=>checkboxGroup(k,g.title,g.items,item[k]||[],'cd')).join('');openModal(c?'Editar infraestructura':'Registrar CD / transformador',`<div class="grid three"><div><label>Área asociada</label><select id="mCdArea">${currentVisit.areas.map(x=>`<option value="${x.id}" ${x.id===item.areaId?'selected':''}>${escapeHtml(areaLabel(x))}</option>`).join('')}</select></div><div><label>CD / Transformador</label><input id="mCdCode" value="${escapeHtml(item.code)}" placeholder="Ej.: 73431TR1 o Sin placa 01"></div><div><label>kVA</label><input id="mCdKva" value="${escapeHtml(item.kva)}" placeholder="Ej.: 75 o N.V."></div><div><label>Propiedad</label><select id="mCdProperty"><option>ENEL</option><option>Comunidad</option><option>Particular</option><option>No determinada</option></select></div><div><label>GPS</label><select id="mCdGps"><option>No capturado</option><option>Exacto</option><option>Aproximado / referencia</option></select></div><div><label>Prioridad</label><select id="mCdPriority"><option>Alta</option><option>Media</option><option>Baja</option></select></div><div><label>Latitud</label><input id="mCdLat" value="${item.lat||''}"></div><div><label>Longitud</label><input id="mCdLng" value="${item.lng||''}"></div><div><label>Estado validado</label><select id="mCdValidated"><option value="">Aceptar sugerencia NITS</option><option>Favorable</option><option>Medio</option><option>Crítico</option></select></div></div><div class="check-groups-modal">${checks}</div><div class="grid four"><div><label>Clientes</label><input id="mClients" type="number" min="0" value="${item.clients||0}"></div><div><label>UNC</label><input id="mUnc" type="number" min="0" value="${item.unc||0}"></div><div><label>Suspensiones</label><input id="mSusp" type="number" min="0" value="${item.susp||0}"></div><div><label>Baldíos</label><input id="mBaldios" type="number" min="0" value="${item.baldios||0}"></div></div><div class="dict-wrap"><label>Observaciones técnicas</label><textarea id="mCdObs" placeholder="Describe la infraestructura con tus propias palabras…">${escapeHtml(item.obs||'')}</textarea><button class="mic-btn" data-target="mCdObs">🎤</button></div><div class="form-actions"><button id="captureCdGps" class="secondary">📍 Capturar GPS</button><button id="saveCd" class="primary">Analizar y guardar</button></div>`);$('mCdProperty').value=item.property;$('mCdGps').value=item.gpsStatus;$('mCdPriority').value=item.priority||'Media';$('mCdValidated').value=item.validatedState||'';bindMicButtons();$('captureCdGps').onclick=()=>captureGps('mCdLat','mCdLng','mCdGps');$('saveCd').onclick=()=>{Object.keys(techGroups).forEach(k=>item[k]=$$(`[data-check-prefix="cd"][data-check-key="${k}"]:checked`).map(x=>x.value));item.areaId=$('mCdArea').value;item.areaLabel=areaLabel(currentVisit.areas.find(x=>x.id===item.areaId));item.code=$('mCdCode').value.trim();item.kva=$('mCdKva').value.trim();item.property=$('mCdProperty').value;item.gpsStatus=$('mCdGps').value;item.lat=$('mCdLat').value;item.lng=$('mCdLng').value;item.priority=$('mCdPriority').value;item.obs=$('mCdObs').value.trim();item.clients=+$('mClients').value||0;item.unc=+$('mUnc').value||0;item.susp=+$('mSusp').value||0;item.baldios=+$('mBaldios').value||0;item.suggestedState=suggestCdState(item);item.validatedState=$('mCdValidated').value||item.suggestedState;item.nitsDescription=describeInfrastructure(item);if(!c)currentVisit.cds.push(item);closeModal();scheduleSave();renderCDs();toast(`NITS sugiere estado ${item.suggestedState}`)}}
function suggestCdState(c){const critical=['Fugas de aceite','Ruido anormal','Conductores deteriorados','Riesgo de contacto','Requiere mantenimiento correctivo','Requiere reemplazo','Base socavada','Construcción artesanal'];const medium=['Requiere mantenimiento preventivo','Empalmes visibles','Flecha excesiva','Baja altura','Vegetación cercana','Cruce por predios privados','Construcción parcialmente normalizada','Requiere extensión BT','Requiere normalización','Inclinados','Fisuras','Corrosión'];const all=[...(c.networkState||[]),...(c.poleState||[]),...(c.transformerState||[]),...(c.construction||[]),...(c.coverage||[])];if(all.some(x=>critical.includes(x)))return 'Crítico';if(c.property!=='ENEL')return 'Medio';if(all.some(x=>medium.includes(x)))return 'Medio';return 'Favorable'}
function listSentence(arr){if(!arr?.length)return '';if(arr.length===1)return arr[0].toLowerCase();return `${arr.slice(0,-1).map(x=>x.toLowerCase()).join(', ')} y ${arr.at(-1).toLowerCase()}`}
function describeInfrastructure(c){const parts=[];if(c.mt?.length&& !c.mt.includes('No aplica'))parts.push(`La red de media tensión presenta configuración ${listSentence(c.mt.filter(x=>!x.startsWith('No ')).map(x=>x.replace(/^MT /,'')))}`);if(c.bt?.length&& !c.bt.includes('No aplica'))parts.push(`la red de baja tensión es ${listSentence(c.bt.filter(x=>!x.startsWith('No ')).map(x=>x.replace(/^BT /,'')))}`);if(c.poleType?.length)parts.push(`se encuentra soportada en postería de ${listSentence(c.poleType)}`);if(c.equipment?.length&&!c.equipment.includes('No se identifican'))parts.push(`se identificaron ${listSentence(c.equipment)}`);if(c.networkState?.length)parts.push(`respecto al estado de las redes, se observaron condiciones como ${listSentence(c.networkState)}`);if(c.poleState?.length)parts.push(`la postería presenta ${listSentence(c.poleState)}`);if(c.transformerState?.length)parts.push(`el transformador presenta ${listSentence(c.transformerState)}`);if(c.construction?.length)parts.push(`la condición constructiva corresponde a ${listSentence(c.construction)}`);if(c.coverage?.length)parts.push(`en materia de cobertura e intervención, se identificó ${listSentence(c.coverage)}`);let out=parts.join('. ');if(c.obs)out+=(out?'. ':'')+improveTechnicalText(c.obs);return out?out.replace(/mt/gi,'MT').replace(/bt/gi,'BT')+'.':'No se registró información técnica suficiente para describir la infraestructura.'}
function improveTechnicalText(t){let s=t.trim();if(!s)return '';s=s[0].toUpperCase()+s.slice(1);s=s.replace(/\s+/g,' ').replace(/\.{2,}/g,'.');return s.endsWith('.')?s:s+'.'}

function renderFindings(){const box=$('findingList');if(!currentVisit.findings.length){box.innerHTML='<div class="empty">No se han registrado hallazgos sociales o territoriales.</div>';return}box.innerHTML=currentVisit.findings.map(f=>`<div class="item-card"><div class="item-top"><div><h4>${escapeHtml(f.category||'Pendiente de clasificar')}</h4><p>${escapeHtml(f.areaLabel||'Sin área')}</p></div><div class="item-actions"><button class="secondary small" data-find-edit="${f.id}">Editar</button><button class="danger small" data-find-delete="${f.id}">Eliminar</button></div></div><p>${escapeHtml(f.nitsText||f.obs)}</p><div>${(f.photos||[]).map(p=>`<span class="tag">📷 ${escapeHtml(p.caption||'Foto')}</span>`).join('')}</div></div>`).join('');box.querySelectorAll('[data-find-edit]').forEach(b=>b.onclick=()=>showFindingModal(currentVisit.findings.find(f=>f.id===b.dataset.findEdit)));box.querySelectorAll('[data-find-delete]').forEach(b=>b.onclick=()=>{if(confirm('¿Eliminar este hallazgo?')){currentVisit.findings=currentVisit.findings.filter(f=>f.id!==b.dataset.findDelete);scheduleSave();renderFindings();renderPhotoGallery()}})}
function renderPhotoGallery(){const box=$('visitPhotoGallery');if(!box)return;const photos=currentVisit.findings.flatMap(f=>(f.photos||[]).map(p=>({...p,area:f.areaLabel,findingId:f.id})));if(!photos.length){box.innerHTML='<div class="empty">Aún no hay fotografías. Agrégalas desde un hallazgo para que queden vinculadas al área activa.</div>';return}box.innerHTML=photos.map(p=>`<div class="visit-photo-item"><img src="${p.dataURL}"><div><b>${escapeHtml(p.caption||'Sin pie de foto')}</b><span>${escapeHtml(p.area||'Sin área')}</span></div></div>`).join('')}
function showFindingModal(f=null){const a=activeArea();if(!a&&!f)return toast('Primero agrega y activa un área');const item=f||{id:uuid(),areaId:a.id,areaLabel:areaLabel(a),obs:'',category:'',nitsText:'',photos:[]};openModal(f?'Editar hallazgo':'Agregar hallazgo',`<div><label>Área asociada</label><select id="mFindingArea">${currentVisit.areas.map(x=>`<option value="${x.id}" ${x.id===item.areaId?'selected':''}>${escapeHtml(areaLabel(x))}</option>`).join('')}</select></div><div class="dict-wrap"><label>Describe lo observado o manifestado</label><textarea id="mFindingObs" placeholder="Ej.: La comunidad manifiesta que el acceso se dificulta por pérdida de banca…">${escapeHtml(item.obs||'')}</textarea><button class="mic-btn" data-target="mFindingObs">🎤</button></div><div><label>Traer fotografías (opcional)</label><input id="mFindingPhotos" type="file" accept="image/*" multiple></div><div id="mPhotoList" class="photo-grid"></div><div class="form-actions"><button id="saveFinding" class="primary">Clasificar y guardar</button></div>`);bindMicButtons();renderModalPhotos(item);$('mFindingPhotos').onchange=async e=>{for(const file of [...e.target.files])item.photos.push(await compressImage(file));renderModalPhotos(item)};$('saveFinding').onclick=()=>{item.areaId=$('mFindingArea').value;item.areaLabel=areaLabel(currentVisit.areas.find(x=>x.id===item.areaId));item.obs=$('mFindingObs').value.trim();if(!item.obs&&!item.photos.length)return toast('Agrega una observación o fotografía');const r=classifyFinding(item.obs);item.category=r.category;item.nitsText=r.text;if(!f)currentVisit.findings.push(item);closeModal();scheduleSave();renderFindings();renderPhotoGallery();toast(`NITS clasificó: ${item.category}`)}}
function classifyFinding(text=''){const t=text.toLowerCase();let category='Social / Comunitario';if(/vía|acceso|placa huella|barro|piedra|banca|carretera|camino|sendero|vehículo/.test(t))category='Acceso y movilidad';if(/predio|propiedad|posesión|invasión|lote|escritura|titular|fiscal/.test(t))category='Predial';if(/desliz|inund|erosión|ronda hídrica|quebrada|ambient|reserva|remoción|geológ|roca/.test(t))category='Ambiental / Riesgo no eléctrico';if(/alcaldía|planeación|entidad|institución|enel|inmel|redes/.test(t))category='Institucional';if(/document|certificado|cédula|recibo técnico|carpeta/.test(t))category='Documental';if(/indígen|afro|migrante|víctima|discapacidad|tecnodepend|adulto mayor|niñ/.test(t))category='Social / Población prioritaria';let s=text.trim().replace(/\s+/g,' ');if(s)s=s[0].toUpperCase()+s.slice(1);s=s.replace(/\b(dicen|dice)\b/gi,'manifestó');if(category==='Acceso y movilidad'&&!/^Durante/.test(s))s=`Durante el recorrido se identificó que ${s.charAt(0).toLowerCase()+s.slice(1)}`;else if(category==='Predial'&&!/^Se/.test(s))s=`Se registró que ${s.charAt(0).toLowerCase()+s.slice(1)}`;else if(category.startsWith('Ambiental')&&!/^Se/.test(s))s=`Se identificó ${s.charAt(0).toLowerCase()+s.slice(1)}`;if(s&&!s.endsWith('.'))s+='.';return {category,text:s||'Hallazgo soportado mediante registro fotográfico.'}}
async function compressImage(file){const data=await fileToDataURL(file);const img=await loadImage(data);const max=1400,scale=Math.min(1,max/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(img,0,0,c.width,c.height);return {id:uuid(),name:file.name,dataURL:c.toDataURL('image/jpeg',.78),original:data,caption:''}}
function fileToDataURL(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
function loadImage(src){return new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=src})}
function renderModalPhotos(item){const box=$('mPhotoList');if(!box)return;box.innerHTML=(item.photos||[]).map(p=>`<div class="photo-card"><img src="${p.dataURL}"><input data-photo-caption="${p.id}" placeholder="Pie de foto" value="${escapeHtml(p.caption||'')}"><div class="photo-actions"><button class="secondary small" data-photo-edit="${p.id}">Rayar</button><button class="danger small" data-photo-remove="${p.id}">Quitar</button></div></div>`).join('');box.querySelectorAll('[data-photo-caption]').forEach(i=>i.oninput=()=>{const p=item.photos.find(x=>x.id===i.dataset.photoCaption);p.caption=i.value});box.querySelectorAll('[data-photo-remove]').forEach(b=>b.onclick=()=>{item.photos=item.photos.filter(x=>x.id!==b.dataset.photoRemove);renderModalPhotos(item)});box.querySelectorAll('[data-photo-edit]').forEach(b=>b.onclick=()=>openImageEditor(item,b.dataset.photoEdit))}
async function openImageEditor(item,photoId){const p=item.photos.find(x=>x.id===photoId);if(!p)return;editorPhotoRef={item,photo:p};const img=await loadImage(p.dataURL);originalEditorImage=p.dataURL;const canvas=$('editCanvas');const maxW=900,scale=Math.min(1,maxW/img.width);canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);$('imageEditor').classList.add('show');setupCanvasDraw()}
function setupCanvasDraw(){const c=$('editCanvas'),ctx=c.getContext('2d');let drawing=false,last=null;const pos=e=>{const r=c.getBoundingClientRect(),p=e.touches?.[0]||e;return {x:(p.clientX-r.left)*c.width/r.width,y:(p.clientY-r.top)*c.height/r.height}};const start=e=>{drawing=true;last=pos(e);e.preventDefault()};const move=e=>{if(!drawing)return;const q=pos(e);ctx.strokeStyle='#d40000';ctx.lineWidth=+$('brushSize').value;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(q.x,q.y);ctx.stroke();last=q;e.preventDefault()};const end=()=>drawing=false;c.onpointerdown=start;c.onpointermove=move;c.onpointerup=end;c.onpointerleave=end;c.ontouchstart=start;c.ontouchmove=move;c.ontouchend=end}

function renderPeople(){const box=$('peopleList');if(!currentVisit.people.length){box.innerHTML='<div class="empty">No hay contactos registrados.</div>';return}box.innerHTML=currentVisit.people.map(p=>`<div class="item-card"><div class="item-top"><div><h4>👤 ${escapeHtml(p.name)}</h4><p>${escapeHtml(p.role||'Habitante')} · ${escapeHtml(p.phone||'Sin teléfono')} · ${escapeHtml(p.areaLabel||'')}</p></div><div class="item-actions"><button class="secondary small" data-person-edit="${p.id}">Editar</button><button class="danger small" data-person-delete="${p.id}">Eliminar</button></div></div><p>${escapeHtml(p.notes||'')}</p></div>`).join('');box.querySelectorAll('[data-person-edit]').forEach(b=>b.onclick=()=>showPersonModal(currentVisit.people.find(x=>x.id===b.dataset.personEdit)));box.querySelectorAll('[data-person-delete]').forEach(b=>b.onclick=()=>{currentVisit.people=currentVisit.people.filter(x=>x.id!==b.dataset.personDelete);scheduleSave();renderPeople()})}
function showPersonModal(p=null){const a=activeArea();const item=p||{id:uuid(),areaId:a?.id||'',areaLabel:areaLabel(a),name:'',role:'',phone:'',notes:''};openModal(p?'Editar contacto':'Agregar contacto',`<div class="grid two"><div><label>Área asociada</label><select id="mPersonArea">${currentVisit.areas.map(x=>`<option value="${x.id}" ${x.id===item.areaId?'selected':''}>${escapeHtml(areaLabel(x))}</option>`).join('')}</select></div><div><label>Nombre</label><input id="mPersonName" value="${escapeHtml(item.name)}"></div><div><label>Rol / relación con la comunidad</label><input id="mPersonRole" value="${escapeHtml(item.role)}" placeholder="Presidencia JAC, líder, habitante…"></div><div><label>Teléfono</label><input id="mPersonPhone" value="${escapeHtml(item.phone)}" inputmode="tel"></div></div><div><label>Observaciones</label><textarea id="mPersonNotes">${escapeHtml(item.notes)}</textarea></div><div class="form-actions"><button id="savePerson" class="primary">Guardar contacto</button></div>`);$('savePerson').onclick=()=>{item.areaId=$('mPersonArea').value;item.areaLabel=areaLabel(currentVisit.areas.find(x=>x.id===item.areaId));item.name=$('mPersonName').value.trim();item.role=$('mPersonRole').value.trim();item.phone=$('mPersonPhone').value.trim();item.notes=$('mPersonNotes').value.trim();if(!item.name)return toast('Escribe el nombre');if(!p)currentVisit.people.push(item);closeModal();scheduleSave();renderPeople()}}

function renderPendings(){const box=$('pendingList');if(!currentVisit.pendings.length){box.innerHTML='<div class="empty">No hay pendientes registrados.</div>';return}box.innerHTML=currentVisit.pendings.map(p=>`<div class="item-card"><div class="item-top"><div><h4>📌 ${escapeHtml(p.text)}</h4><p>${escapeHtml(p.responsible||'Responsable por definir')} · ${p.date?`Alerta ${p.date}`:'Sin fecha'} · ${escapeHtml(p.status||'Abierto')}</p></div><div class="item-actions">${p.date?`<button class="secondary small" data-cal="${p.id}">Calendario</button>`:''}<button class="secondary small" data-pending-edit="${p.id}">Editar</button><button class="danger small" data-pending-delete="${p.id}">Eliminar</button></div></div></div>`).join('');box.querySelectorAll('[data-pending-edit]').forEach(b=>b.onclick=()=>showPendingModal(currentVisit.pendings.find(x=>x.id===b.dataset.pendingEdit)));box.querySelectorAll('[data-pending-delete]').forEach(b=>b.onclick=()=>{currentVisit.pendings=currentVisit.pendings.filter(x=>x.id!==b.dataset.pendingDelete);scheduleSave();renderPendings()});box.querySelectorAll('[data-cal]').forEach(b=>b.onclick=()=>downloadICS(currentVisit.pendings.find(x=>x.id===b.dataset.cal)))}
function showPendingModal(p=null){const a=activeArea();const item=p||{id:uuid(),areaId:a?.id||'',areaLabel:areaLabel(a),text:'',responsible:'ENEL',status:'Abierto',date:''};openModal(p?'Editar pendiente':'Agregar pendiente',`<div><label>Área asociada</label><select id="mPendingArea">${currentVisit.areas.map(x=>`<option value="${x.id}" ${x.id===item.areaId?'selected':''}>${escapeHtml(areaLabel(x))}</option>`).join('')}</select></div><div class="dict-wrap"><label>Pendiente</label><textarea id="mPendingText" placeholder="Ej.: Programar reunión para gestión documental después del proceso de Redes">${escapeHtml(item.text)}</textarea><button class="mic-btn" data-target="mPendingText">🎤</button></div><div class="grid three"><div><label>Responsable</label><select id="mPendingResp"><option>ENEL</option><option>Redes</option><option>Gestión Social</option><option>INMEL</option><option>Comunidad</option><option>Usuario</option><option>Otro</option></select></div><div><label>Estado</label><select id="mPendingStatus"><option>Abierto</option><option>En gestión</option><option>En espera</option><option>Cumplido</option><option>Cerrado</option></select></div><div><label>Fecha de alerta (opcional)</label><input id="mPendingDate" type="date" value="${item.date||''}"></div></div><div class="form-actions"><button id="savePending" class="primary">Guardar pendiente</button></div>`);$('mPendingResp').value=item.responsible;$('mPendingStatus').value=item.status;bindMicButtons();$('savePending').onclick=()=>{item.areaId=$('mPendingArea').value;item.areaLabel=areaLabel(currentVisit.areas.find(x=>x.id===item.areaId));item.text=$('mPendingText').value.trim();item.responsible=$('mPendingResp').value;item.status=$('mPendingStatus').value;item.date=$('mPendingDate').value;if(!item.text)return toast('Escribe el pendiente');if(!p)currentVisit.pendings.push(item);closeModal();scheduleSave();renderPendings()}}
function downloadICS(p){if(!p.date)return;const dt=p.date.replaceAll('-','')+'T130000';const content=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//GS Asistente//ES\r\nBEGIN:VEVENT\r\nUID:${p.id}@gsasistente\r\nDTSTART:${dt}\r\nSUMMARY:${p.text.replace(/[,;]/g,' ')}\r\nDESCRIPTION:${p.areaLabel||''}\r\nBEGIN:VALARM\r\nTRIGGER:-PT60M\r\nACTION:DISPLAY\r\nDESCRIPTION:Recordatorio GS Asistente\r\nEND:VALARM\r\nEND:VEVENT\r\nEND:VCALENDAR`;downloadBlob(new Blob([content],{type:'text/calendar'}),`Pendiente_${currentVisit.id}.ics`)}

function bindMicButtons(){$$('.mic-btn').forEach(b=>b.onclick=()=>startDictation(b.dataset.target))}
function startDictation(target){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast('El dictado no está disponible en este navegador');const r=new SR();r.lang='es-CO';r.interimResults=false;r.onstart=()=>toast('Escuchando…');r.onresult=e=>{const el=$(target);el.value=(el.value?el.value+' ':'')+e.results[0][0].transcript;el.dispatchEvent(new Event('input',{bubbles:true}))};r.onerror=()=>toast('No fue posible completar el dictado');r.start()}

function analyzeTerritory(){const t=currentVisit.territory;const parts=[];if(t.community?.length)parts.push(`La comunidad presenta características como ${listSentence(t.community)}`);if(t.priority?.length)parts.push(`se identificaron grupos de atención prioritaria, entre ellos ${listSentence(t.priority)}`);if(t.property?.length)parts.push(`en relación con la ocupación y la propiedad del suelo, se registraron condiciones de ${listSentence(t.property)}`);if(t.risks?.length)parts.push(`el territorio presenta factores de riesgo no eléctrico asociados a ${listSentence(t.risks)}`);if(t.access?.length)parts.push(`el acceso se realiza mediante ${listSentence(t.access)}`);if(t.road?.length)parts.push(`las vías presentan ${listSentence(t.road)}`);let s=parts.join('. ');if(currentVisit.territoryObs)s+=(s?'. ':'')+improveTechnicalText(currentVisit.territoryObs);return s?s+'.':'No se registraron elementos suficientes para elaborar una caracterización general del territorio.'}
function analyzeManagement(){const m=currentVisit.management;const parts=[];if(m.topics?.length)parts.push(`Durante la gestión social se abordaron temas relacionados con ${listSentence(m.topics)}`);if(m.obs)parts.push(improveTechnicalText(m.obs));if(m.nextAction)parts.push(`Como próxima gestión prevista se registró: ${m.nextAction}`);return parts.length?parts.join('. ').replace(/\.\./g,'.')+'.':'No se registró una jornada formal de socialización o reunión con la comunidad.'}
function totals(){return currentVisit.cds.reduce((a,c)=>({clients:a.clients+(+c.clients||0),unc:a.unc+(+c.unc||0),susp:a.susp+(+c.susp||0),baldios:a.baldios+(+c.baldios||0)}),{clients:0,unc:0,susp:0,baldios:0})}
function energyRecovered(){const t=totals();return (t.unc+t.susp)*150}
function objectiveText(){const acts=[];if(currentVisit.cds.length)acts.push('reconocimiento general de la infraestructura eléctrica');if(currentVisit.management.meeting==='Sí'||currentVisit.management.topics?.length)acts.push('gestión y socialización con la comunidad');if(currentVisit.findings.length)acts.push('identificación de condiciones sociales y territoriales');if(!acts.length)acts.push('reconocimiento preliminar del territorio');return `Se realizó visita de Gestión Social en el municipio de ${currentVisit.municipio||'________________'}, con el propósito de efectuar ${listSentence(acts)}. El recorrido comprendió ${currentVisit.areas.length||'las'} área(s), cuya información fue organizada para apoyar la toma de decisiones y las gestiones posteriores.`}
function conclusionText(){const t=totals(),states=currentVisit.cds.map(c=>c.validatedState||c.suggestedState);const parts=[];if(currentVisit.cds.length)parts.push(`Se identificaron ${currentVisit.cds.length} Centro(s) de Distribución, con predominio de clasificación ${mode(states)||'no evaluada'}`);if(t.unc+t.susp)parts.push(`se registró un universo potencial de ${t.unc+t.susp} usuarios entre UNC y suspensiones`);if(currentVisit.findings.length)parts.push(`los hallazgos sociales y territoriales se concentraron en ${[...new Set(currentVisit.findings.map(f=>f.category))].join(', ')}`);if(currentVisit.pendings.length)parts.push(`quedaron ${currentVisit.pendings.filter(p=>!['Cumplido','Cerrado'].includes(p.status)).length} pendientes abiertos o en seguimiento`);return parts.length?parts.join('. ')+'.':'La información recopilada constituye una base preliminar para definir las gestiones posteriores en el territorio.'}
function mode(arr){const m={};arr.filter(Boolean).forEach(x=>m[x]=(m[x]||0)+1);return Object.entries(m).sort((a,b)=>b[1]-a[1])[0]?.[0]}
function recommendationText(){const rec=[];if(currentVisit.cds.some(c=>['Crítico','Medio'].includes(c.validatedState||c.suggestedState)))rec.push('realizar la revisión técnica de los CD que presentan requerimientos de intervención o validación');if(currentVisit.pendings.some(p=>p.responsible==='ENEL'||p.responsible==='Redes'))rec.push('dar seguimiento institucional a las gestiones pendientes asignadas a ENEL o al componente de Redes');if(currentVisit.management.nextAction)rec.push(currentVisit.management.nextAction.toLowerCase());if(currentVisit.findings.some(f=>f.category==='Predial'))rec.push('validar las condiciones prediales antes de avanzar con actuaciones que requieran soporte documental');return rec.length?`Se recomienda ${listSentence(rec)}.`:'Se recomienda conservar el seguimiento del territorio y actualizar la información cuando se realicen nuevas visitas.'}

function buildPreview(){collectTopFields();if(!currentVisit.sede||!currentVisit.municipio||!currentVisit.zona){toast('Completa Sede, Municipio y Zona antes de la vista previa');showScreen('visitScreen');$('generalCard').scrollIntoView({behavior:'smooth'});return;}const t=totals(),areas=[...new Set(currentVisit.areas.map(areaLabel))];const cRows=currentVisit.cds.map(c=>`<tr><td></td><td>${escapeHtml(c.code||'Sin identificar')}</td><td>${escapeHtml(c.kva||'N.V.')}</td><td>${escapeHtml(c.property||'No determinada')}</td><td>${escapeHtml((+c.unc||0)+(+c.susp||0))}</td><td><span class="state-pill ${c.validatedState==='Favorable'?'state-fav':c.validatedState==='Crítico'?'state-crit':'state-med'}">${escapeHtml(c.validatedState||c.suggestedState||'No evaluado')}</span></td><td>${escapeHtml(c.nitsDescription||'')}</td></tr>`).join('')||'<tr><td colspan="7">No se registró infraestructura eléctrica.</td></tr>';const fRows=currentVisit.findings.map(f=>`<tr><td>${escapeHtml(f.areaLabel||'')}</td><td>${escapeHtml(f.category||'')}</td><td>${escapeHtml(f.nitsText||f.obs||'')}</td></tr>`).join('')||'<tr><td colspan="3">No se registraron hallazgos sociales o territoriales.</td></tr>';const pRows=currentVisit.pendings.map(p=>`<tr><td>${escapeHtml(p.text)}</td><td>${escapeHtml(p.responsible)}</td><td>${escapeHtml(p.status)}</td></tr>`).join('')||'<tr><td colspan="3">No se registraron pendientes.</td></tr>';const photos=currentVisit.findings.flatMap(f=>(f.photos||[]).map(p=>({...p,area:f.areaLabel})));const glossaryRows=dynamicGlossary().map(([k,v])=>`<tr><td><b>${k}</b></td><td>${v}</td></tr>`).join('');$('previewDocument').innerHTML=`<div class="paper-page cover-page"><div class="cover-top"><div class="inmel-logo">IN<span>MEL</span></div></div><div class="cover-center"><div class="process">GESTIÓN SOCIAL</div><h1>DIAGNÓSTICO<br>TÉCNICO - SOCIAL</h1><div class="redline"></div><p>${escapeHtml(currentVisit.municipio||'MUNICIPIO')} · ${escapeHtml(areas.join(', ')||'ÁREA POR DEFINIR')}</p></div><div class="cover-art"></div><div class="cover-meta"><div><b>ID</b><br>${currentVisit.id}</div><div><b>Fecha</b><br>${currentVisit.date}</div><div><b>Sede</b><br>${escapeHtml(currentVisit.sede)}</div><div><b>Zona</b><br>${escapeHtml(currentVisit.zona)}</div></div></div><div class="paper-page"><div class="doc-head"><div class="process-logo">GS Gestión Social</div><small>ID ${currentVisit.id}</small></div>${previewSection(1,'Objeto de la visita',objectiveText())}${previewSection(2,'Caracterización general del territorio',analyzeTerritory())}<div class="section-title"><span class="number-box">3</span><h2>Indicadores de caracterización</h2></div><div class="kpi-grid"><div class="kpi-card"><strong>${currentVisit.cds.length}</strong><span>CIRCUITOS</span><small>Centros de distribución evaluados.</small></div><div class="kpi-card"><strong>${t.unc+t.susp}</strong><span>PREDIOS UNC</span><small>Usuarios por normalizar</small></div><div class="kpi-card"><strong>${t.clients}</strong><span>CLIENTES</span><small>Predios con medidores</small></div><div class="kpi-card"><strong>${energyRecovered().toLocaleString('es-CO')}</strong><span>kWh/mes</span><small>Consumo proyectado total a recuperar</small></div></div><div class="section-title"><span class="number-box">4</span><h2>Diagnóstico de infraestructura</h2></div><table class="doc-table"><thead><tr><th>Orden de servicio</th><th>CD</th><th>kVA</th><th>Propiedad</th><th>UNC</th><th>Estado</th><th>Descripción de infraestructura</th></tr></thead><tbody>${cRows}</tbody></table><div class="section-title"><span class="number-box">5</span><h2>Hallazgos identificados</h2></div><table class="doc-table"><thead><tr><th>Localidad / Sector</th><th>Categoría</th><th>Hallazgo</th></tr></thead><tbody>${fRows}</tbody></table></div><div class="paper-page"><div class="doc-head"><div class="process-logo">GS Gestión Social</div><small>ID ${currentVisit.id}</small></div>${previewSection(6,'Gestión social desarrollada',analyzeManagement())}<div class="section-title"><span class="number-box">7</span><h2>Pendientes y próxima gestión</h2></div><table class="doc-table"><thead><tr><th>Pendiente</th><th>Responsable</th><th>Estado</th></tr></thead><tbody>${pRows}</tbody></table>${previewSection(8,'Conclusiones',conclusionText())}${previewSection(9,'Recomendaciones',recommendationText())}${photos.length?`<div class="section-title"><span class="number-box">10</span><h2>Registro fotográfico</h2></div><div class="photo-report-grid">${photos.map(p=>`<div class="photo-report"><img src="${p.dataURL}"><p>${escapeHtml(p.caption||p.area||'Registro fotográfico')}</p></div>`).join('')}</div>`:''}<div class="section-title"><span class="number-box">11</span><h2>Glosario</h2></div><table class="doc-table"><tbody>${glossaryRows}</tbody></table></div>`;showScreen('previewScreen')}
function previewSection(n,title,text){return `<div class="section-title"><span class="number-box">${n}</span><h2>${title}</h2></div><p class="doc-paragraph">${escapeHtml(text)}</p>`}
function dynamicGlossary(){const text=JSON.stringify(currentVisit).toLowerCase();return Object.entries(glossary).filter(([k])=>text.includes(k.toLowerCase())||['UNC','BT','MT','CD','Favorable','Medio','Crítico'].includes(k))}

async function generateWord(){if(!window.docx)return toast('No se pudo cargar el generador Word');collectTopFields();await saveCurrent();const d=window.docx;const {Document,Packer,Paragraph,TextRun,Table,TableRow,TableCell,WidthType,AlignmentType,HeadingLevel,ImageRun,Header,Footer,PageNumber,PageBreak,ShadingType,VerticalAlign,BorderStyle}=d;const red='D40000',dark='2F343A',white='FFFFFF',grey='E5E7EB';const children=[];const inmel=await fetchArrayBuffer('inmel-logo.png'),gs=await fetchArrayBuffer('gs-logo.png');const firstHeader=new Header({children:[new Paragraph({alignment:AlignmentType.RIGHT,children:[new ImageRun({data:inmel,transformation:{width:130,height:46}})]})]});const defaultHeader=new Header({children:[new Paragraph({border:{bottom:{color:red,style:BorderStyle.SINGLE,size:12}},children:[new ImageRun({data:gs,transformation:{width:135,height:40}}),new TextRun({text:`     ID ${currentVisit.id}`,color:'667085',size:18})]})]});const footer=new Footer({children:[new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({text:'Página ',size:16,color:'667085'}),new TextRun({children:[PageNumber.CURRENT],size:16,color:'667085'})]})]});
  children.push(new Paragraph({spacing:{before:2600},children:[new TextRun({text:'GESTIÓN SOCIAL',bold:true,color:red,size:32})]}),new Paragraph({spacing:{before:260},children:[new TextRun({text:'DIAGNÓSTICO TÉCNICO - SOCIAL',bold:true,color:dark,size:58})]}),new Paragraph({spacing:{before:300},children:[new TextRun({text:`${currentVisit.municipio||''} · ${currentVisit.areas.map(areaLabel).join(', ')}`,color:'667085',size:24})]}),new Paragraph({spacing:{before:2500},border:{top:{color:red,style:BorderStyle.SINGLE,size:30}},children:[new TextRun({text:`ID: ${currentVisit.id}     Fecha: ${currentVisit.date}     Sede: ${currentVisit.sede}     Zona: ${currentVisit.zona}`,size:22,color:dark})]}),new Paragraph({children:[new PageBreak()]}));
  const addTitle=(n,title)=>children.push(new Paragraph({spacing:{before:260,after:120},children:[new TextRun({text:` ${n} `,bold:true,color:white,shading:{type:ShadingType.CLEAR,fill:dark},size:24}),new TextRun({text:`  ${title}`,bold:true,color:dark,size:28})]}));
  const addPara=text=>children.push(new Paragraph({alignment:AlignmentType.JUSTIFIED,spacing:{after:160,line:320},children:[new TextRun({text,size:22,font:'Arial'})]}));
  addTitle(1,'Objeto de la visita');addPara(objectiveText());addTitle(2,'Caracterización general del territorio');addPara(analyzeTerritory());addTitle(3,'Indicadores de caracterización');
  const t=totals();children.push(kpiTable(d,[['CIRCUITOS',currentVisit.cds.length,'Centros de distribución evaluados.'],['PREDIOS UNC',t.unc+t.susp,'Usuarios por normalizar'],['CLIENTES',t.clients,'Predios con medidores'],['kWh/mes',energyRecovered().toLocaleString('es-CO'),'Consumo proyectado total a recuperar']],red,dark));
  addTitle(4,'Diagnóstico de infraestructura');children.push(infraTableDoc(d,currentVisit.cds,dark));
  addTitle(5,'Hallazgos identificados');children.push(findingsTableDoc(d,currentVisit.findings,dark));
  addTitle(6,'Gestión social desarrollada');addPara(analyzeManagement());
  addTitle(7,'Pendientes y próxima gestión');children.push(pendingTableDoc(d,currentVisit.pendings,dark));
  addTitle(8,'Conclusiones');addPara(conclusionText());addTitle(9,'Recomendaciones');addPara(recommendationText());
  const photos=currentVisit.findings.flatMap(f=>(f.photos||[]).map(p=>({...p,area:f.areaLabel})));
  if(photos.length){
    addTitle(10,'Registro fotográfico');
    for(let i=0;i<photos.length;i+=2){
      const pair=photos.slice(i,i+2);
      const cells=[0,1].map(j=>{
        const p=pair[j];
        if(!p) return new TableCell({children:[new Paragraph({children:[]})]});
        return new TableCell({children:[
          new Paragraph({alignment:AlignmentType.CENTER,children:[new ImageRun({data:dataURLtoUint8(p.dataURL),transformation:{width:260,height:180}})]}),
          new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({text:p.caption||p.area||'Registro fotográfico',size:18,font:'Arial'})]})
        ]});
      });
      children.push(new Table({width:{size:100,type:WidthType.PERCENTAGE},rows:[new TableRow({children:cells})]}));
    }
  }
  addTitle(11,'Glosario');children.push(glossaryTableDoc(d,dynamicGlossary(),dark));
  const doc=new Document({styles:{default:{document:{run:{font:'Arial',size:22}}}},sections:[{properties:{titlePage:true,page:{margin:{top:720,right:720,bottom:720,left:720}}},headers:{first:firstHeader,default:defaultHeader},footers:{default:footer},children}]});const blob=await Packer.toBlob(doc);const area=currentVisit.areas[0]?.name||'Visita';downloadBlob(blob,`${currentVisit.id}_${safeName(currentVisit.municipio)}_${safeName(area)}.docx`);currentVisit.reportGenerated=true;currentVisit.reportDate=dateLocal();currentVisit.status='Informe generado';await saveCurrent();renderVisitHeader();toast('Word generado')}
function cellText(d,text,opts={}){return new d.TableCell({shading:opts.fill?{type:d.ShadingType.CLEAR,fill:opts.fill}:undefined,verticalAlign:d.VerticalAlign.CENTER,children:[new d.Paragraph({alignment:opts.center?d.AlignmentType.CENTER:d.AlignmentType.LEFT,children:[new d.TextRun({text:String(text??''),bold:!!opts.bold,color:opts.color||'000000',size:opts.size||18,font:'Arial'})]})]})}
function kpiTable(d,items,red,dark){const cells=items.map(([label,value,sub])=>new d.TableCell({children:[new d.Paragraph({alignment:d.AlignmentType.CENTER,children:[new d.TextRun({text:String(value),bold:true,color:'111111',size:34,font:'Arial'})]}),new d.Paragraph({alignment:d.AlignmentType.CENTER,children:[new d.TextRun({text:label,bold:true,color:'113954',size:16,font:'Arial'})]}),new d.Paragraph({alignment:d.AlignmentType.CENTER,children:[new d.TextRun({text:sub||'',color:'113954',size:13,font:'Arial'})]})]}));return new d.Table({width:{size:100,type:d.WidthType.PERCENTAGE},rows:[new d.TableRow({children:cells})]})}
function infraTableDoc(d,cds,dark){const head=new d.TableRow({children:['Orden de servicio','CD','kVA','Propiedad','UNC','Estado','Descripción de infraestructura'].map(x=>cellText(d,x,{fill:dark,color:'FFFFFF',bold:true,center:true}))});const rows=(cds.length?cds:[{}]).map(c=>new d.TableRow({children:[cellText(d,''),cellText(d,c.code||'No registrado'),cellText(d,c.kva||'N.V.',{center:true}),cellText(d,c.property||'',{center:true}),cellText(d,(+c.unc||0)+(+c.susp||0),{center:true}),cellText(d,c.validatedState||c.suggestedState||'No evaluado',{fill:(c.validatedState||c.suggestedState)==='Favorable'?'DFF4E5':(c.validatedState||c.suggestedState)==='Crítico'?'FFE1E1':'FFF0C9',bold:true,center:true}),cellText(d,c.nitsDescription||'')]}));return new d.Table({width:{size:100,type:d.WidthType.PERCENTAGE},rows:[head,...rows]})}
function findingsTableDoc(d,findings,dark){const head=new d.TableRow({children:['Localidad / Sector','Categoría','Hallazgo'].map(x=>cellText(d,x,{fill:dark,color:'FFFFFF',bold:true,center:true}))});const rows=(findings.length?findings:[{}]).map(f=>new d.TableRow({children:[cellText(d,f.areaLabel||'No registrado'),cellText(d,f.category||'',{center:true}),cellText(d,f.nitsText||f.obs||'')]}));return new d.Table({width:{size:100,type:d.WidthType.PERCENTAGE},rows:[head,...rows]})}
function pendingTableDoc(d,items,dark){const head=new d.TableRow({children:['Pendiente','Responsable','Estado'].map(x=>cellText(d,x,{fill:dark,color:'FFFFFF',bold:true,center:true}))});const rows=(items.length?items:[{}]).map(p=>new d.TableRow({children:[cellText(d,p.text||'No se registraron pendientes'),cellText(d,p.responsible||'',{center:true}),cellText(d,p.status||'',{center:true})]}));return new d.Table({width:{size:100,type:d.WidthType.PERCENTAGE},rows:[head,...rows]})}
function glossaryTableDoc(d,items,dark){return new d.Table({width:{size:100,type:d.WidthType.PERCENTAGE},rows:items.map(([k,v])=>new d.TableRow({children:[cellText(d,k,{fill:dark,color:'FFFFFF',bold:true}),cellText(d,v)]}))})}
function dataURLtoUint8(dataURL){const b=atob(dataURL.split(',')[1]);const a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);return a}
async function fetchArrayBuffer(url){return await (await fetch(url)).arrayBuffer()}
function safeName(s=''){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'_').replace(/^_|_$/g,'')||'SinNombre'}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function exportBackup(v=currentVisit){const copy=structuredClone(v);downloadBlob(new Blob([JSON.stringify(copy,null,2)],{type:'application/json'}),`Respaldo_GS_${v.id}.json`)}
async function importBackup(file){try{const v=JSON.parse(await file.text());if(!v.id)throw Error();normalizeImported(v);await idbPut('visits',v);renderVisitList();toast('Respaldo importado')}catch(e){toast('El archivo no es un respaldo válido')}}
function normalizeImported(v){v.areas||=[];v.cds||=[];v.findings||=[];v.people||=[];v.pendings||=[];v.territory||={};v.management||={topics:[],obs:'',nextAction:'',meeting:'No'};v.updatedAt=nowISO()}

function bindEvents(){fillSede();bindAutosave();$('newVisitBtn').onclick=createVisit;$('goSavedBtn').onclick=()=>$('visitList').scrollIntoView({behavior:'smooth'});$('backHomeBtn').onclick=async()=>{await saveCurrent();showScreen('homeScreen')};$('previewBtn').onclick=buildPreview;$('previewBottomBtn').onclick=buildPreview;$('backVisitBtn').onclick=()=>showScreen('visitScreen');$('generateWordBtn').onclick=generateWord;$('addAreaBtn').onclick=()=>showAreaModal();$('addCdBtn').onclick=()=>showCdModal();$('addFindingBtn').onclick=()=>showFindingModal();$('addPhotoFindingBtn').onclick=()=>showFindingModal();$('addPersonBtn').onclick=()=>showPersonModal();$('addPendingBtn').onclick=()=>showPendingModal();$('closeModalBtn').onclick=closeModal;$('modal').onclick=e=>{if(e.target===$('modal'))closeModal()};$('exportBackupBtn').onclick=()=>exportBackup();$('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=e=>e.target.files[0]&&importBackup(e.target.files[0]);$('themeBtn').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('gs_theme',document.body.classList.contains('dark')?'dark':'light')};$$('[data-go]').forEach(b=>b.onclick=()=>$(b.dataset.go).scrollIntoView({behavior:'smooth',block:'start'}));bindMicButtons();$('closeEditorBtn').onclick=()=>$('imageEditor').classList.remove('show');$('clearDrawingBtn').onclick=async()=>{const img=await loadImage(originalEditorImage),c=$('editCanvas');c.getContext('2d').clearRect(0,0,c.width,c.height);c.getContext('2d').drawImage(img,0,0,c.width,c.height)};$('saveDrawingBtn').onclick=()=>{editorPhotoRef.photo.dataURL=$('editCanvas').toDataURL('image/jpeg',.86);$('imageEditor').classList.remove('show');renderModalPhotos(editorPhotoRef.item);renderPhotoGallery();toast('Imagen actualizada')}}

async function init(){await openDB();if(localStorage.getItem('gs_theme')==='dark')document.body.classList.add('dark');bindEvents();renderVisitList();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{})}
document.addEventListener('DOMContentLoaded',init);
})();
